  "implementation": "def solve(case):
    import json
    nodes = case['nodes']
    core = case['core_distance']
    dists = case['distances']
    # Build edges with mutual reachability
    edges = []
    for u, v, d in dists:
        if u > v:
            u, v = v, u
        mr = max(core[u], core[v], d)
        edges.append((mr, u, v))
    # Sort deterministically
    edges.sort(key=lambda x: (x[0], x[1], x[2]))
    # Union-Find
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst_edges = []
    total = 0.0
    for w, u, v in edges:
        if union(u, v):
            mst_edges.append({'u': u, 'v': v, 'weight': w})
            total += w
            if len(mst_edges) == len(nodes) - 1:
                break
    if len(mst_edges) != len(nodes) - 1:
        raise ValueError('Input graph is disconnected; cannot form MST')
    return {'edges': mst_edges, 'total_weight': total}"
